export function renameKey(obj: Record<string, unknown>, from: string, to: string): Record<string, unknown> {
  if (!Object.hasOwn(obj, from)) return { ...obj };
  const copy: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) {
    if (key === from) copy[to] = obj[key];
    else copy[key] = obj[key];
  }
  return copy;
}

