export function createHistory<T>(initial: T) {
  const past: T[] = [];
  let value = initial;
  return {
    current(): T {
      return value;
    },
    set(next: T): void {
      past.push(value);
      value = next;
    },
    undo(): T {
      if (past.length) {
        value = past.pop() as T;
      }
      return value;
    },
    undoCount(): number {
      return past.length;
    },
  };
}

