export function isBalanced(s: string): boolean {
  const closerFor: Record<string, string> = { '(': ')', '[': ']', '{': '}' };
  const expected: string[] = [];
  for (const ch of s) {
    if (closerFor[ch]) {
      expected.push(closerFor[ch]);
    } else if (ch === ')' || ch === ']' || ch === '}') {
      if (expected.pop() !== ch) return false;
    }
  }
  return expected.length === 0;
}

