bootforge/ts-apps/generics/generic-data-.solution:
export function rotate<T>(arr: T[], n: number): T[] {
  if (arr.length === 0) return [];
  const queue = [...arr];
  const steps = n % arr.length;
  for (let i = 0; i < steps; i++) {
    queue.push(queue.shift() as T);
  }
  return queue;
}

