  const stack: number[] = [];
  const results: (number | null)[] = [];
  for (const op of ops) {
    if (op === 'pop') {
      results.push(stack.length ? (stack.pop() as number) : null);
    } else if (op.startsWith('push:')) {
      stack.push(Number(op.slice(5)));
    }
  }
  return results;
}

