export function josephus(n: number, k: number): number {
  // build [1..n]; while more than one remains: rotate k-1, then eliminate the front
}

bootforge/ts-apps/generics/generic-data-.solution:
export function josephus(n: number, k: number): number {
  const queue: number[] = [];
  for (let i = 1; i <= n; i++) queue.push(i);
  while (queue.length > 1) {
    for (let i = 0; i < k - 1; i++) {
      queue.push(queue.shift() as number);
    }
    queue.shift();
  }
  return queue[0];
}

