export function createMinStack() {
  // hint: two parallel stacks — values, and the min "so far" at each depth
}

bootforge/ts-apps/generics/generic-data-.solution:
export function createMinStack() {
  const values: number[] = [];
  const mins: number[] = [];
  return {
    push(n: number): void {
      values.push(n);
      const currentMin = mins.length ? mins[mins.length - 1] : Infinity;
      mins.push(Math.min(n, currentMin));
    },
    pop(): number | null {
      if (!values.length) return null;
      mins.pop();
      return values.pop() as number;
    },
    min(): number | null {
      return mins.length ? mins[mins.length - 1] : null;
    },
  };
}

