type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function summarizeResults<T>(results: Result<T>[]): {
  succeeded: number;
  failed: number;
  values: T[];
  firstError: string | null;
} {
  let succeeded = 0;
  let failed = 0;
  const values: T[] = [];
  let firstError: string | null = null;
  for (const r of results) {
    if (r.ok) {
      succeeded++;
      values.push(r.value);
    } else {
      failed++;
      if (firstError === null) firstError = r.error;
    }
  }
  return { succeeded, failed, values, firstError };
}

