  | { type: 'ADD'; tab: string }
  | { type: 'CLOSE'; tab: string };

export function tabsReducer(state: TabsState, action: TabsAction): TabsState {
  switch (action.type) {
    case 'SELECT':
      return state.tabs.includes(action.tab) ? { ...state, active: action.tab } : state;
    case 'ADD':
      return state.tabs.includes(action.tab) ? state : { ...state, tabs: [...state.tabs, action.tab] };
    case 'CLOSE': {
      if (!state.tabs.includes(action.tab) || state.tabs.length === 1) return state;
      const tabs = state.tabs.filter((t) => t !== action.tab);
      const active = state.active === action.tab ? tabs[0] : state.active;
      return { tabs, active };
    }
  }
}

