type CounterAction = { type: 'INC' } | { type: 'ADD'; amount: number } | { type: 'RESET' };

export function finalCount(actions: CounterAction[]): number {
  let count = 0;
  for (const action of actions) {
    if (action.type === 'INC') count += 1;
    else if (action.type === 'ADD') count += action.amount;
    else count = 0;
  }
  return count;
}

