bootforge/ts-apps/modeling/type-safe-sta.solution:
type FormState = { values: Record<string, string>; touched: string[]; submitted: boolean };
type FormAction =
  | { type: 'SET_FIELD'; field: string; value: string }
  | { type: 'SUBMIT' }
  | { type: 'RESET' };

export function formReducer(state: FormState, action: FormAction): FormState {
  switch (action.type) {
    case 'SET_FIELD': {
      if (state.submitted) return state;
      const touched = state.touched.includes(action.field)
        ? [...state.touched]
        : [...state.touched, action.field];
      return {
        values: { ...state.values, [action.field]: action.value },
        touched,
        submitted: false,
      };
    }
    case 'SUBMIT':
      return { ...state, submitted: true };
    case 'RESET':
      return { values: {}, touched: [], submitted: false };
  }
}

