export function checkFieldTypes(obj: Record<string, unknown>, schema: Record<string, string>): string[] {
  const errors: string[] = [];
  for (const key of Object.keys(schema)) {
    if (!Object.hasOwn(obj, key)) {
      errors.push(key + ': missing');
    } else if (typeof obj[key] !== schema[key]) {
      errors.push(key + ': expected ' + schema[key]);
    }
  }
  return errors.sort();
}

