type Settings = { theme: 'light' | 'dark'; fontSize: number; autosave: boolean };
type ParseOutcome = { ok: true; value: Settings } | { ok: false; errors: string[] };

export function parseSettings(input: unknown): ParseOutcome {
  if (typeof input !== 'object' || input === null) {
    return { ok: false, errors: ['not an object'] };
  }
  const rec = input as Record<string, unknown>;
  const errors: string[] = [];

  let theme: 'light' | 'dark' = 'light';
  if (Object.hasOwn(rec, 'theme')) {
    if (rec.theme === 'light' || rec.theme === 'dark') theme = rec.theme;
    else errors.push('theme: invalid');
  }

  let fontSize = 14;
  if (Object.hasOwn(rec, 'fontSize')) {
    if (typeof rec.fontSize === 'number' && rec.fontSize >= 8 && rec.fontSize <= 32) {
      fontSize = rec.fontSize;
    } else {
      errors.push('fontSize: invalid');
    }
  }

  let autosave = true;
  if (Object.hasOwn(rec, 'autosave')) {
    if (typeof rec.autosave === 'boolean') autosave = rec.autosave;
    else errors.push('autosave: invalid');
  }

  if (errors.length) return { ok: false, errors };
  return { ok: true, value: { theme, fontSize, autosave } };
}

